// Sync-over-async: blocks a thread-pool thread waiting on a Task,
// starving the pool under load and queuing every other request behind it.
public IActionResult GetOrderBad(int id)
{
    var order = _orderService.GetOrderAsync(id).Result; // ✖ blocks
    return Ok(order);
}

// Correct: async all the way, thread returns to the pool while awaiting.
public async Task<IActionResult> GetOrderGood(int id)
{
    var order = await _orderService.GetOrderAsync(id); // ✔ non-blocking
    return Ok(order);
}

