// Captive dependency: Scoped DbContext captured by a Singleton
// -> accumulates tracked entities for the app's entire lifetime
public class BadCacheService // registered as Singleton
{
    private readonly AppDbContext _db; // ✖ Scoped injected into Singleton
    public BadCacheService(AppDbContext db) => _db = db;
}

// Fix: inject IServiceScopeFactory and create a scope per operation
public class GoodCacheService
{
    private readonly IServiceScopeFactory _scopeFactory;
    public GoodCacheService(IServiceScopeFactory scopeFactory) => _scopeFactory = scopeFactory;

    public async Task<Product> GetProductAsync(int id)
    {
        using var scope = _scopeFactory.CreateScope();
        var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
        return await db.Products.FindAsync(id); // Scoped DbContext, disposed with the scope
    }
}

// Event handler leak: publisher holds subscriber alive forever
publisher.SomethingHappened += Handler; // subscribed, never removed -> leak
// publisher.SomethingHappened -= Handler; // must unsubscribe on disposal

// Feature flags let you disable a broken feature instantly without a redeploy —
// one of the fastest mitigation levers during an incident.
public class CheckoutController : ControllerBase
{
    private readonly IFeatureManager _features;

    [HttpPost("checkout")]
    public async Task<IActionResult> Checkout(OrderRequest request)
    {
        if (await _features.IsEnabledAsync("NewPaymentFlow"))
        {
            return await _newPaymentService.ProcessAsync(request); // ✖ suspected of the incident
        }
        return await _legacyPaymentService.ProcessAsync(request); // ✔ known-good fallback
    }
}

// Flip "NewPaymentFlow" off centrally (config/flag service) -> instant mitigation,
// no build, no deploy, no waiting on a pipeline.
